  ('INTERCEPTION', 1, 'Interception', ARRAY['DEF','MID','CDM','CM','CB','LB','RB'], ARRAY['PRIMARY'], 0, '{}'::jsonb, '{"interceptions":1}'::jsonb),
  ('RECOVERY', 1, 'Recovery', ARRAY['DEF','MID','CDM','CM','LB','RB'], ARRAY['PRIMARY'], 0, '{}'::jsonb, '{"recoveries":1}'::jsonb),
