CREATE TABLE match_data.match_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id uuid NOT NULL REFERENCES match_data.matches(id) ON DELETE RESTRICT,
  client_event_id uuid NOT NULL,
  sequence integer NOT NULL CHECK (sequence > 0),
  action_code varchar(64) NOT NULL,
  action_catalog_version integer NOT NULL,
  side platform.match_side NOT NULL,
  period_number smallint NOT NULL CHECK (period_number BETWEEN 1 AND 4),
  match_elapsed_seconds integer NOT NULL CHECK (match_elapsed_seconds >= 0),
  client_occurred_at timestamptz,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  recorded_by_member_id uuid NOT NULL,
  qualifiers jsonb NOT NULL DEFAULT '{}'::jsonb,
  state platform.event_state NOT NULL DEFAULT 'CONFIRMED',
  source varchar(16) NOT NULL DEFAULT 'LOGGER' CHECK (source IN ('LOGGER', 'OFFLINE_SYNC', 'ADMIN', 'SYSTEM')),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (match_id, sequence),
  UNIQUE (match_id, client_event_id),
  UNIQUE (id, match_id),
  FOREIGN KEY (action_code, action_catalog_version)
    REFERENCES match_data.action_catalog(code, version),
  CHECK (jsonb_typeof(qualifiers) = 'object')
);
CREATE INDEX match_events_match_sequence_ix ON match_data.match_events (match_id, sequence);
CREATE INDEX match_events_match_time_ix ON match_data.match_events (match_id, match_elapsed_seconds, sequence);
CREATE INDEX match_events_action_ix ON match_data.match_events (action_code, recorded_at DESC);

CREATE TABLE match_data.match_event_subjects (
  match_id uuid NOT NULL,
  event_id uuid NOT NULL REFERENCES match_data.match_events(id) ON DELETE CASCADE,
  participant_id uuid NOT NULL,
  role varchar(24) NOT NULL CHECK (role IN (
    'PRIMARY', 'SCORER', 'ASSISTER', 'OPPONENT', 'GOALKEEPER', 'PLAYER_ON', 'PLAYER_OFF', 'CARD_RECIPIENT'
  )),
  ordinal smallint NOT NULL DEFAULT 1 CHECK (ordinal > 0),
  PRIMARY KEY (event_id, role, ordinal),
  FOREIGN KEY (event_id, match_id) REFERENCES match_data.match_events(id, match_id) ON DELETE CASCADE,
  FOREIGN KEY (participant_id, match_id) REFERENCES match_data.match_participants(id, match_id)
);
CREATE INDEX match_event_subjects_participant_ix ON match_data.match_event_subjects (participant_id, event_id);

-- This linking record is the only marker that an event has been undone. The
-- reversed event continues to exist unchanged; all projections exclude it.
CREATE TABLE match_data.event_reversals (
  reversal_event_id uuid PRIMARY KEY REFERENCES match_data.match_events(id) ON DELETE RESTRICT,
  reversed_event_id uuid NOT NULL REFERENCES match_data.match_events(id) ON DELETE RESTRICT,
  reason varchar(500) NOT NULL CHECK (char_length(btrim(reason)) >= 3),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (reversed_event_id),
  CHECK (reversal_event_id <> reversed_event_id)
);

CREATE OR REPLACE FUNCTION match_data.validate_event_reversal()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  reversal_match uuid;
  reversed_match uuid;
  reversal_action varchar(64);
BEGIN
  SELECT match_id, action_code INTO reversal_match, reversal_action
  FROM match_data.match_events WHERE id = NEW.reversal_event_id;
  SELECT match_id INTO reversed_match FROM match_data.match_events WHERE id = NEW.reversed_event_id;
  IF reversal_match IS DISTINCT FROM reversed_match THEN
    RAISE EXCEPTION 'reversal and reversed event must belong to the same match';
  END IF;
  IF reversal_action <> 'EVENT_REVERSAL' THEN
    RAISE EXCEPTION 'reversal event action must be EVENT_REVERSAL';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER event_reversals_validate BEFORE INSERT ON match_data.event_reversals
  FOR EACH ROW EXECUTE FUNCTION match_data.validate_event_reversal();

-- ============================================================================
-- platform schema — cross-cutting reliability/audit data.
-- The outbox record is inserted in the same transaction as a match event.
-- ============================================================================

CREATE TABLE platform.idempotency_records (
  scope varchar(160) NOT NULL, -- e.g. user UUID + route name
  idempotency_key varchar(128) NOT NULL,
  request_fingerprint bytea NOT NULL,
  response_status smallint NOT NULL CHECK (response_status BETWEEN 100 AND 599),
  response_body jsonb NOT NULL,
  resource_id uuid,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (scope, idempotency_key),
  CHECK (expires_at > created_at)
);
CREATE INDEX idempotency_records_expiry_ix ON platform.idempotency_records (expires_at);

CREATE TABLE platform.outbox_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  aggregate_type varchar(64) NOT NULL,
  aggregate_id uuid NOT NULL,
  aggregate_sequence integer,
  event_type varchar(128) NOT NULL,
  payload jsonb NOT NULL,
  trace_id varchar(64),
  occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  published_at timestamptz,
  publish_attempts integer NOT NULL DEFAULT 0 CHECK (publish_attempts >= 0),
  locked_until timestamptz,
  last_error varchar(1000),
  CHECK (jsonb_typeof(payload) = 'object')
);
CREATE INDEX outbox_unpublished_ix ON platform.outbox_events (occurred_at, id)
  WHERE published_at IS NULL;

CREATE TABLE platform.audit_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL,
  actor_user_id uuid,
  actor_member_id uuid,
  action varchar(100) NOT NULL,
  resource_type varchar(64) NOT NULL,
  resource_id uuid NOT NULL,
  before_state jsonb,
  after_state jsonb,
  request_id varchar(64),
  ip inet,
  occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX audit_log_resource_ix ON platform.audit_log (resource_type, resource_id, occurred_at DESC);
CREATE INDEX audit_log_org_time_ix ON platform.audit_log (organization_id, occurred_at DESC);

-- ============================================================================
-- read_model schema — owned by projection service. Rebuildable from ledger.
-- ============================================================================

CREATE TABLE read_model.consumer_inbox (
  consumer_name varchar(100) NOT NULL,
  source_event_id uuid NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (consumer_name, source_event_id)
);

CREATE TABLE read_model.match_snapshots (
  match_id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  status platform.match_status NOT NULL,
  home_name varchar(100) NOT NULL,
  away_name varchar(100) NOT NULL,
  home_score smallint NOT NULL CHECK (home_score >= 0),
  away_score smallint NOT NULL CHECK (away_score >= 0),
  current_period_number smallint,
  elapsed_seconds integer NOT NULL DEFAULT 0,
  last_event_sequence integer NOT NULL DEFAULT 0,
  generated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX match_snapshots_org_status_ix ON read_model.match_snapshots (organization_id, status, generated_at DESC);

CREATE TABLE read_model.match_timeline_entries (
  match_id uuid NOT NULL,
  event_id uuid NOT NULL,
  sequence integer NOT NULL,
  minute smallint NOT NULL CHECK (minute >= 0),
  side platform.match_side NOT NULL,
  action_code varchar(64) NOT NULL,
  action_label varchar(100) NOT NULL,
  actor_display_name varchar(100),
  is_public boolean NOT NULL DEFAULT true,
  is_reversed boolean NOT NULL DEFAULT false,
  generated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (match_id, event_id),
  UNIQUE (match_id, sequence)
);
CREATE INDEX match_timeline_public_ix ON read_model.match_timeline_entries (match_id, sequence DESC)
  WHERE is_public AND NOT is_reversed;

CREATE TABLE read_model.player_match_stat_lines (
  match_id uuid NOT NULL,
  participant_id uuid NOT NULL,
  player_id uuid,
  side platform.match_side NOT NULL,
  metrics jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_event_sequence integer NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (match_id, participant_id),
  CHECK (jsonb_typeof(metrics) = 'object')
);
CREATE INDEX player_match_stat_lines_player_ix ON read_model.player_match_stat_lines (player_id, updated_at DESC)
  WHERE player_id IS NOT NULL;

CREATE TABLE read_model.team_match_stat_lines (
  match_id uuid NOT NULL,
  side platform.match_side NOT NULL,
  metrics jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_event_sequence integer NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (match_id, side),
  CHECK (jsonb_typeof(metrics) = 'object')
);

CREATE TABLE read_model.competition_standing_rows (
  competition_id uuid NOT NULL,
  stage_id uuid,
  team_id uuid NOT NULL,
  rank smallint NOT NULL CHECK (rank > 0),
  played smallint NOT NULL DEFAULT 0 CHECK (played >= 0),
  won smallint NOT NULL DEFAULT 0 CHECK (won >= 0),
  drawn smallint NOT NULL DEFAULT 0 CHECK (drawn >= 0),
  lost smallint NOT NULL DEFAULT 0 CHECK (lost >= 0),
  goals_for smallint NOT NULL DEFAULT 0 CHECK (goals_for >= 0),
  goals_against smallint NOT NULL DEFAULT 0 CHECK (goals_against >= 0),
  points smallint NOT NULL DEFAULT 0 CHECK (points >= 0),
  calculated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (competition_id, stage_id, team_id),
  UNIQUE NULLS NOT DISTINCT (competition_id, stage_id, rank)
);
CREATE INDEX competition_standing_rows_sort_ix
  ON read_model.competition_standing_rows (competition_id, stage_id, rank);

